pub(super) fn analysis__test_recommendation__normalize_recommendation_config(
    mut raw_config: Value,
) -> Result<Value> {
    let mut config: Value;
    let mut recommendations: Value;
    let mut required_oracles: Value;
    let mut signals: Value;
    let mut verification_commands: Value;
    config = builtin(
        "dict",
        &[{
            let first = raw_config.clone();
            if truth(&first) { first } else { json!({}) }
        }],
    )?;
    recommendations = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(
            &config,
            &json!("recommendations"),
            Value::Array(vec![]),
        ))? {
            let mut rec = current;
            if !(rec.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__test_recommendation__normalize_recommendation(
                rec.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    required_oracles = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(
            &config,
            &json!("required_oracles"),
            Value::Array(vec![]),
        ))? {
            let mut oracle = current;
            if !(oracle.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__test_recommendation__normalize_oracle(
                oracle.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    verification_commands = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(
            &config,
            &json!("verification_commands"),
            Value::Array(vec![]),
        ))? {
            let mut cmd = current;
            if !(cmd.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__test_recommendation__normalize_command(
                cmd.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    signals = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(&config, &json!("signals"), Value::Array(vec![])))? {
            let mut signal = current;
            if !(signal.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__test_recommendation__normalize_signal(
                signal.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    return Ok(Value::Object(
        [
            ("recommendations".into(), recommendations.clone()),
            ("required_oracles".into(), required_oracles.clone()),
            (
                "verification_commands".into(),
                verification_commands.clone(),
            ),
            ("signals".into(), signals.clone()),
            (
                "analysis_scope".into(),
                json!(values::text(&{
                    let first = get(&config, &json!("analysis_scope"), json!(""));
                    if truth(&first) { first } else { json!("") }
                })),
            ),
            ("input_refs".into(), {
                let mut collected_values = Vec::new();
                for current in sequence(&get(&config, &json!("input_refs"), Value::Array(vec![])))?
                {
                    let mut r#ref = current;
                    if !(truth(&json!(values::text(&r#ref)))) {
                        continue;
                    }
                    collected_values.push(json!(values::text(&r#ref)));
                }
                Value::Array(collected_values)
            }),
            (
                "confidence".into(),
                json!(number(&{
                    let first = get(&config, &json!("confidence"), json!(0.0));
                    if truth(&first) { first } else { json!(0.0) }
                })?),
            ),
            (
                "limits".into(),
                analysis__test_recommendation__normalize_limits(get(
                    &config,
                    &json!("limits"),
                    json!({}),
                ))?,
            ),
            (
                "actionable_taxonomy_used".into(),
                json!(truth(&get(
                    &config,
                    &json!("actionable_taxonomy_used"),
                    json!(true)
                ))),
            ),
            (
                "oracle_validation_enabled".into(),
                json!(truth(&get(
                    &config,
                    &json!("oracle_validation_enabled"),
                    json!(true)
                ))),
            ),
            (
                "command_verification_enabled".into(),
                json!(truth(&get(
                    &config,
                    &json!("command_verification_enabled"),
                    json!(true)
                ))),
            ),
        ]
        .into_iter()
        .collect(),
    ));
}

