pub(super) fn analysis__test_recommendation__recommendation_from_signal(
    mut signal: Value,
) -> Result<Value> {
    let mut action: Value;
    let mut command: Value;
    let mut required_oracle: Value;
    let mut signal_type: Value;
    let mut target: Value;
    signal_type = indexed(&signal, &json!("signal_type"))?;
    target = {
        let first = indexed(&signal, &json!("test_id"))?;
        if truth(&first) {
            first
        } else {
            {
                let first = indexed(&signal, &json!("risk_id"))?;
                if truth(&first) {
                    first
                } else {
                    indexed(&signal, &json!("requirement_id"))?
                }
            }
        }
    };
    if !(truth(&target)) {
        return Ok(Value::Null);
    }
    action = json!("generic");
    required_oracle = json!("");
    command = json!("");
    if contains(
        &unique(vec![
            json!("no_oracle"),
            json!("missing_oracle"),
            json!("oracle_weak"),
        ]),
        &signal_type,
    ) {
        action = json!("add_or_modify_test");
        required_oracle = json!("executable_oracle");
        command = json!("run targeted test with oracle");
    } else {
        if contains(
            &unique(vec![
                json!("flaky"),
                json!("mixed_outcome"),
                json!("environment_flake"),
            ]),
            &signal_type,
        ) {
            action = json!("rerun_test");
            command = json!("rerun affected test with retry/environment capture");
        } else {
            if contains(
                &unique(vec![json!("impact"), json!("affected_test")]),
                &signal_type,
            ) {
                action = json!("rerun_test");
                command = json!("rerun impacted test");
            } else {
                if contains(
                    &unique(vec![
                        json!("blocked"),
                        json!("manual_review_required"),
                        json!("unsupported_claim"),
                    ]),
                    &signal_type,
                ) {
                    action = json!("manual_review");
                    command = json!("open manual review packet");
                } else {
                    if contains(
                        &unique(vec![json!("coverage_gap"), json!("mutation_survived")]),
                        &signal_type,
                    ) {
                        action = json!("add_test");
                        required_oracle = json!("mutation_backed_oracle");
                        command = json!("run coverage and mutation check");
                    }
                }
            }
        }
    }
    return Ok(Value::Object(
        [
            ("recommendation_id".into(), {
                let first = indexed(&signal, &json!("signal_id"))?;
                if truth(&first) {
                    first
                } else {
                    json!(format!("rec:{}", values::text(&target)))
                }
            }),
            ("action".into(), action.clone()),
            ("target".into(), target.clone()),
            ("risk_id".into(), indexed(&signal, &json!("risk_id"))?),
            ("required_oracle".into(), required_oracle.clone()),
            ("verification_command".into(), command.clone()),
            (
                "confidence".into(),
                (if !equal(&action, &json!("generic")) {
                    json!(0.85)
                } else {
                    json!(0.4)
                }),
            ),
            ("sourceRef".into(), indexed(&signal, &json!("sourceRef"))?),
        ]
        .into_iter()
        .collect(),
    ));
}
